const FloatingLabelInput = ({
  label,
  value,
  onChangeText,
  leftIcon,
  rightIcon,
  multiline = false,
  style,
  error,
  placeholder,
  disabled,
  showErrorMessage = false,
  maxLength,
  autoCapitalize = 'none',
  numberOfLines = 3,
  customStyle,
  secureTextEntry = false,
  keyboardType = 'default',
}) => {
  const { theme } = useThemeContext();
  const styles = styless(theme);
  const [isFocused, setIsFocused] = useState(false);
  const animatedLabel = useRef(new Animated.Value(value ? 1 : 0)).current;

  useEffect(() => {
    Animated.timing(animatedLabel, {
      toValue: isFocused || value ? 1 : 0,
      duration: 200,
      useNativeDriver: false,
    }).start();
  }, [isFocused, value, error]);

  const labelStyle = {
    position: 'absolute',
    left: leftIcon ? verticalScale(40) : verticalScale(15),
    maxWidth: '90%',
    transform: leftIcon && [
      {
        translateX: animatedLabel.interpolate({
          inputRange: [0, 1],
          outputRange: [verticalScale(0), verticalScale(-20)],
        }),
      },
    ],

    color: animatedLabel.interpolate({
      inputRange: [0, 1],
      outputRange: [
        theme.colors.textTertiary,
        error ? theme.colors.red : theme.colors.primary,
      ],
    }),

    top: animatedLabel.interpolate({
      inputRange: [0, 1],
      outputRange: [verticalScale(15), verticalScale(-8)],
    }),

    fontSize: animatedLabel.interpolate({
      inputRange: [0, 1],
      outputRange: [verticalScale(14), verticalScale(12)],
    }),

    // color: error
    //   ? theme.colors.red
    //   : isFocused || value
    //   ? theme.colors.primary
    //   : theme.colors.textTertiary,

    backgroundColor: disabled
      ? theme.colors.bgSecondary
      : theme.colors.backgroundColor,
    paddingHorizontal: verticalScale(4),
    borderRadius: verticalScale(10),
    fontFamily: 'Lato-Regular',
  };

  return (
    <View style={[style]}>
      <View
        style={[
          styles.container,
          {
            borderColor: error
              ? theme.colors.red
              : isFocused
              ? theme.colors.primary
              : theme.colors.border,
            backgroundColor: disabled
              ? theme.colors.bgSecondary
              : theme.colors.backgroundColor,
          },
