        >
          {label}
        </Animated.Text>

        <TextInput
          style={[
            styles.input,
            {
              paddingLeft: leftIcon ? verticalScale(40) : verticalScale(15),
              paddingRight: rightIcon ? verticalScale(35) : verticalScale(15),
              minHeight: multiline ? verticalScale(70) : verticalScale(50),
