const CustomBottomTabBar = ({ state, navigation, theme, styles }) => {
  const activeRoute = state.routes[state.index];
  useEffect(() => {
    console.log('Active Tab:', activeRoute.name);
  }, [state.index]);

  const insets = useSafeAreaInsets();

  const getBottomMargin = () => {
    if (Platform.OS === 'ios') {
      return -verticalScale(insets.bottom + 10);
    }
    return insets.bottom > 25 ? -verticalScale(0) : -verticalScale(24);
  };

  const handleTabPress = index => {
    const route = state.routes[index];
    const event = navigation.emit({
      type: 'tabPress',
      target: route.key,
    });

    if (state.index !== index && !event.defaultPrevented) {
      navigation.navigate(route.name);
    }
  };

  return (
    <View
      style={{
        marginBottom: getBottomMargin(),
        alignSelf: 'flex-start',
        justifyContent: 'flex-start',
      }}
    >
      <ImageBackground
        source={Images.Union}
        resizeMode="stretch"
        style={styles.background}
      >
        <TabButton
          {...TAB_CONFIG[0]}
          Icon={
            state.index === 0 ? BOTTOMTABICONS.HomeActive : BOTTOMTABICONS.Home
          }
          isFocused={state.index === 0}
          onPress={() => handleTabPress(0)}
          styles={styles}
          theme={theme}
        />
        <TabButton
          {...TAB_CONFIG[1]}
          Icon={
            state.index === 1
              ? BOTTOMTABICONS.PolicyActive
              : BOTTOMTABICONS.Policy
          }
          isFocused={state.index === 1}
          onPress={() => handleTabPress(1)}
          styles={styles}
          theme={theme}
        />

        <View style={styles.tabItem}>
          <TouchableOpacity
            style={styles.filterButton}
            activeOpacity={0.8}
            onPress={() => {
              handleTabPress(2);
            }}
          >
            <LinearGradient
              colors={[theme.colors.linear2, theme.colors.linear2]}
              start={{ x: 0, y: 0 }}
              end={{ x: 0, y: 1 }}
              style={{
                flex: 1,
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: verticalScale(30),
              }}
            >
              <Filter />
            </LinearGradient>
          </TouchableOpacity>
          <Text
            style={[
              styles.labelText,
              {
                marginStart: verticalScale(2),
              },
              state.index !== 2 && {
                color: theme.colors.textTertiary,
                fontFamily: 'Lato-Regular',
              },
            ]}
          >
            {TAB_CONFIG[2].label}
          </Text>
        </View>
        <TabButton
          {...TAB_CONFIG[3]}
          Icon={
