const CompareModal = ({
  showCompareModal,
  setShowCompareModal,
  quotesList = [],
  referenceId,
  onUpdate,
}) => {
  const { theme } = useThemeContext();
  const styles = useMemo(() => createStyles(theme), [theme]);
  const { mutate: compareQuotes } = useCompareQuotes();
  const insets = useSafeAreaInsets();

  const opacity = useSharedValue(0);
  const [isVisible, setIsVisible] = useState(false);
  const { updateCompareRefID } = useMotorDetalisStore();

  useEffect(() => {
    if (showCompareModal) {
      setIsVisible(true);
      opacity.value = withTiming(1, { duration: 300 });
    } else {
      opacity.value = withTiming(0, { duration: 300 }, finished => {
        finished && runOnJS(setIsVisible)(false);
      });
    }
  }, [showCompareModal]);

  const backdropStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
  }));

  const containerStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
    transform: [{ translateY: withTiming(showCompareModal ? 0 : 50) }],
  }));

  const handleCompare = useCallback(() => {
    if (quotesList.length < MIN_PLANS) {
      Alert.alert(
        'Selection Required',
        `Please select at least ${MIN_PLANS} plans to compare!`,
      );
      return;
    }

    if (quotesList.length > MAX_PLANS) {
      Alert.alert(
        'Too Many Plans',
        `You can select up to ${MAX_PLANS} plans only!`,
      );
      return;
    }

    compareQuotes({
      referenceId,
      data: { ids: quotesList.map(q => q._id) },
    });

    updateCompareRefID(referenceId);

    setShowCompareModal(false);
  }, [quotesList, referenceId]);

  const renderPlans = useMemo(
    () =>
      quotesList.map(item => (
        <QuoteCard
          key={item._id}
          item={item}
          theme={theme}
          styles={styles}
          onRemove={() => onUpdate(item)}
        />
      )),
    [quotesList, styles],
  );

  if (!isVisible) return null;

  return (
    <Animated.View style={[styles.backdrop, backdropStyle]}>
      <TouchableOpacity
        style={StyleSheet.absoluteFill}
        activeOpacity={1}
        onPress={() => setShowCompareModal(false)}
      />

      <Animated.View
        style={[
          styles.container,
          containerStyle,
          { bottom: insets.bottom + 140 },
        ]}
      >
        <View style={styles.header}>
          <View style={styles.placeholder} />
          <Text style={styles.title}>Compare Plans</Text>
          <TouchableOpacity onPress={() => setShowCompareModal(false)}>
            <Text style={styles.closeBtn}>✕</Text>
          </TouchableOpacity>
        </View>

        {quotesList.length === 0 ? (
          <View style={styles.noDataContainer}>
            <NoData />
          </View>
        ) : (
          <ScrollView showsVerticalScrollIndicator={false}>
            {renderPlans}
          </ScrollView>
        )}

        <View style={styles.horizontalLine} />

        {quotesList.length > 1 && (
          <CustomButton
            title="Compare Plans"
            buttonStyle={styles.compareButton}
            isShowIcon
            onPress={handleCompare}
          />
        )}
      </Animated.View>
    </Animated.View>
  );
};

export default CompareModal;

