const AvilModal = ({ handleClose, isInput, currentOffer }) => {
  const { theme } = useThemeContext();
  const { user } = useAuthStore();
  const styles = getStyles(theme);
  const [valueCode, setValueCode] = useState('');
  const [isValid, setIsValid] = useState(true);
  const { mutate: availOffer } = useAvailOffers();

  const handleCodeSubmit = async () => {
    if (!currentOffer?._id) return;

    const payload = {
      discountCode: valueCode,
    };

    availOffer(
      { id: currentOffer._id, data: payload },
      {
        onSuccess: res => {
          setValueCode('');
          handleClose();
        },
        onError: err => {
          console.error(err);
          setValueCode('');
          setIsValid(false);
        },
      },
    );
  };

  useEffect(() => {
    if (valueCode?.length === 4) {
      handleCodeSubmit();
    }
  }, [valueCode]);

  // Reset state when modal opens
  useEffect(() => {
    setValueCode('');
    setIsValid(true);
  }, [currentOffer]);

  const renderOfferInfo = () => {
    if (!isInput || !currentOffer) return null;

    const discountText =
      currentOffer?.discountType === 'percentage'
        ? `${currentOffer?.discountValue}% OFF`
        : `${currentOffer?.discountValue} AED OFF`;

    return (
      <View>
        <Text style={styles.companyName}>
          {currentOffer?.partner?.companyName}{' '}
          <Text style={styles.discountText}>({discountText})</Text>
        </Text>
      </View>
    );
  };

  const renderCodeInput = () => {
    if (!isInput) return null;

    return (
      <View style={styles.codeInputContainer}>
        <CodeInput
          value={valueCode}
          onChangeText={setValueCode}
          isValid={isValid}
          setIsValid={setIsValid}
        />
      </View>
    );
  };

  return (
    <View style={styles.overlay}>
      <ImageBackground
        source={Images.card}
        resizeMode="contain"
        style={styles.modalContainer}
      >
        <Pressable onPress={handleClose} style={styles.closeButton}>
          <Icon
            name="close"
            size={moderateScale(24)}
            color={theme.colors.backgroundColor}
          />
        </Pressable>
        <View style={styles.content}>
          <View style={styles.mainContent}>
            {renderOfferInfo()}
            <Text style={styles.userName}>{user?.fullName || 'User Name'}</Text>
            {renderCodeInput()}
          </View>
        </View>
      </ImageBackground>
    </View>
  );
};

