import React, { useState, useEffect, useRef } from 'react';
import { View, TextInput, StyleSheet } from 'react-native';
import { useThemeContext } from '@theme/ThemeProvider';
import { verticalScale, moderateScale } from '@constants/metrics';

const CodeInput = ({ onChangeText, isValid, setIsValid, autoFocus = true }) => {
  const { theme } = useThemeContext();
  const styles = getStyles(theme);
  const [digits, setDigits] = useState(['', '', '', '']);
  const inputRefs = useRef([]);

  useEffect(() => {
    if (autoFocus) {
      setTimeout(() => {
        inputRefs.current[0]?.focus();
      }, 300);
    }
  }, [autoFocus]);

  useEffect(() => {
    if (!isValid) {
      setDigits(['', '', '', '']);
      setTimeout(() => {
        inputRefs.current[0]?.focus();
      }, 100);
      setIsValid(true);
    }
  }, [isValid, setIsValid]);

  useEffect(() => {
    const code = digits.join('');
    if (code.length === 4) {
      onChangeText(code);
    }
  }, [digits]);

  const focusNext = (index, value) => {
    if (value && index < 3) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const focusPrevious = (index, key) => {
    if (key === 'Backspace' && index > 0 && !digits[index]) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const handleChangeText = (text, index) => {
    const numericValue = text.replace(/[^0-9]/g, '');

    if (numericValue.length <= 1) {
      const newDigits = [...digits];
      newDigits[index] = numericValue;
      setDigits(newDigits);

      if (numericValue && index < 3) {
        focusNext(index, numericValue);
      }
    }
  };

  const handleKeyPress = (e, index) => {
    if (e.nativeEvent.key === 'Backspace') {
      const newDigits = [...digits];

      if (!digits[index] && index > 0) {
        newDigits[index - 1] = '';
        setDigits(newDigits);
        inputRefs.current[index - 1]?.focus();
      } else if (digits[index]) {
        newDigits[index] = '';
        setDigits(newDigits);
      }
    }
  };

  return (
    <View style={styles.inputsContainer}>
      {[0, 1, 2, 3].map(index => (
        <TextInput
          key={index}
          ref={ref => (inputRefs.current[index] = ref)}
          style={[styles.input]}
          value={digits[index]}
          onChangeText={text => handleChangeText(text, index)}
          onKeyPress={e => handleKeyPress(e, index)}
          keyboardType="number-pad"
          maxLength={1}
          autoFocus={index === 0 && autoFocus}
        />
      ))}
    </View>
  );
};

export default CodeInput;

