import React, {
  useState,
  useCallback,
  useMemo,
  useEffect,
  useRef,
} from 'react';
import { View, Text, FlatList, StyleSheet, Dimensions } from 'react-native';
import { moderateScale, verticalScale } from '@constants/metrics';
