import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import AsyncStorage from '@react-native-async-storage/async-storage';

export const useAuthStore = create(
  persist(
    (set, get) => ({
      token: null,
      user: null,
      _hasHydrated: false,
      onBoarded: false,
      userDetailsUpdate: false,

      setAuth: ({ token, user }) => set({ token, user }),
      setToken: token => set({ token }),
      setUser: user => set({ user }),
      setOnBoarded: onBoarded => set({ onBoarded }),
      setUserDetailsUpdate: userDetailsUpdate => set({ userDetailsUpdate }),
      logout: () =>
        set({
          token: null,
          user: null,
          userDetailsUpdate: false,
        }),

      setHasHydrated: hasHydrated => set({ _hasHydrated: hasHydrated }),
      isHydrated: () => get()._hasHydrated,
    }),
    {
      name: 'auth-store',
      storage: createJSONStorage(() => AsyncStorage),

      partialize: state => ({
        token: state.token,
        user: state.user,
        onBoarded: state.onBoarded,
        userDetailsUpdate: state.userDetailsUpdate,
      }),

      onRehydrateStorage: () => (state, error) => {
        if (error) {
          console.error('Auth store hydration error:', error);
        } else {
          console.log('Auth store hydrated successfully');
        }
        useAuthStore.getState().setHasHydrated(true);
      },
    },
  ),
);

export const authStore = {
  get token() {
    const state = useAuthStore.getState();
    return state._hasHydrated ? state.token : null;
  },

  get user() {
    const state = useAuthStore.getState();
    return state._hasHydrated ? state.user : null;
  },

  get isHydrated() {
    return useAuthStore.getState()._hasHydrated;
  },

  setAuth: ({ token, user }) =>
    useAuthStore.getState().setAuth({ token, user }),
  setToken: token => useAuthStore.getState().setToken(token),
  setOnBoarded: onBoarded => useAuthStore.getState().setOnBoarded(onBoarded),
  setUser: user => useAuthStore.getState().setUser(user),
  logout: () => useAuthStore.getState().logout(),
  setUserDetailsUpdate: () =>
    useAuthStore.getState().setUserDetailsUpdate(userDetailsUpdate),

  waitForHydration: () => {
    return new Promise(resolve => {
      if (useAuthStore.getState()._hasHydrated) {
        resolve(useAuthStore.getState());
        return;
      }

      const unsubscribe = useAuthStore.subscribe(
        state => state._hasHydrated,
        hasHydrated => {
          if (hasHydrated) {
            unsubscribe();
            resolve(useAuthStore.getState());
          }
        },
      );
    });
  },
};

export const useHydratedAuth = () => {
  const auth = useAuthStore();

  if (!auth._hasHydrated) {
    return {
      token: null,
      user: null,
      isLoading: true,
      onBoarded: false,
      userDetailsUpdate: false,
      isHydrated: false,
      ...auth,
    };
  }

  return {
    ...auth,
    isLoading: false,
    isHydrated: true,
  };
};

import React from 'react';
import { Text, StyleSheet, View } from 'react-native';
import { formatNumber } from './formateNumber';
import { verticalScale } from '@constants/metrics';
import { useThemeContext } from '@theme/ThemeProvider';

export const isNumber = value => {
  return !isNaN(parseFloat(value)) && isFinite(value);
};

// Strip HTML tags from string
export const stripHtmlTags = html => {
  if (!html || typeof html !== 'string') return html;
  return html.replace(/<[^>]*>/g, '').trim();
};

// MOTOR INSURANCE RENDERERS
export const renderComparisonCell = (cell, rowIndex, colIndex, rowData) => {
  const { theme } = useThemeContext();
  const styles = style(theme);

  if (cell === undefined || cell === null) {
    return (
      <Text style={[styles.cellText, styles.notApplicableText]}>
        Not Applicable
      </Text>
    );
  }

  if (rowData?.type === 'boolean') {
    return (
      <Text
        style={[
          styles.cellText,
          cell ? styles.applicableText : styles.notApplicableText,
        ]}
      >
        {cell ? 'Applicable' : 'Not Applicable'}
      </Text>
    );
  }

  if (rowData?.type === 'price') {
    return <Text style={styles.cellText}>AED {formatNumber(cell)}</Text>;
  }

  if (typeof cell === 'string' && cell.startsWith('AED')) {
    return <Text style={styles.cellText}>{cell}</Text>;
  }

  if (isNumber(cell)) {
    return (
      <Text style={[styles.cellText, styles.applicableText]}>
        {cell == '0' ? 'Applicable' : cell}
      </Text>
    );
  }

  if (cell === '✕') {
    return <Text style={[styles.cellText, styles.notApplicableText]}>✕</Text>;
  }

  return <Text style={styles.cellText}>{cell}</Text>;
};

export const renderCoverageCell = (cell, rowIndex, colIndex, coverage) => {
  const { theme } = useThemeContext();
  const styles = style(theme);
  if (cell === undefined || cell === null) {
    return (
      <Text style={[styles.cellText, styles.notApplicableText]}>
        Not Applicable
      </Text>
    );
  }

  // Handle Loss & Damage special case
  if (coverage?.Title === 'Loss & Damage' || cell === 'Vehicle Value') {
    const carValue = coverage?.carValues?.[colIndex];
    return (
      <Text
        style={[
          styles.cellText,
          cell ? styles.applicableText : styles.notApplicableText,
        ]}
      >
        {cell ? 'Applicable' : 'Not Applicable'}
      </Text>
    );
  }

  if (!isNumber(cell) && cell) {
    return <Text style={[styles.cellText, styles.applicableText]}>{cell}</Text>;
  }

  return (
    <Text style={[styles.cellText, styles.applicableText]}>
      {cell == '0' ? 'Applicable' : 'Applicable'}
    </Text>
  );
};

export const renderBenefitCell = (cell, rowIndex, colIndex, benefit) => {
  const { theme } = useThemeContext();
  const styles = style(theme);
  if (cell === undefined || cell === null) {
    return (
      <Text style={[styles.cellText, styles.notApplicableText]}>
        Not Applicable
      </Text>
    );
  }

  const limitValue = benefit?.limitValues?.[colIndex];

  if (limitValue?.limitAmount > 0 && !cell) {
    return (
      <Text style={styles.cellText}>
        {`${limitValue.limitAmount} ${limitValue.limitUnit}`}
      </Text>
    );
  }

  if (limitValue?.limitAmount > 0) {
    return <Text style={styles.cellText}>{`${cell}`}</Text>;
  }

  if (cell && typeof cell === 'string' && cell.startsWith('AED')) {
    return <Text style={styles.cellText}>{cell}</Text>;
  }

  if (cell && /\d/.test(cell)) {
    return <Text style={styles.cellText}>{cell}</Text>;
  }

  return (
    <Text style={[styles.cellText, styles.applicableText]}>
      {cell || 'Applicable'}
    </Text>
  );
};

// HEALTH INSURANCE RENDERERS
export const renderHealthComparisonCell = (cell, rowIndex, colIndex, row) => {
  const { theme } = useThemeContext();
  const styles = style(theme);
  if (cell === undefined || cell === null) {
    return <Text style={[styles.cellText, styles.notApplicableText]}>-</Text>;
  }

  // Handle "Contact us for price" or "Price upon request"
  if (
    typeof cell === 'string' &&
    (cell.includes('Contact us') || cell.includes('Price upon request'))
  ) {
    return (
      <Text style={[styles.cellText, styles.warningText]} numberOfLines={2}>
        {cell}
      </Text>
    );
  }

  // Handle AED prices
  if (typeof cell === 'string' && cell.startsWith('AED')) {
    return <Text style={[styles.cellText, styles.priceText]}>{cell}</Text>;
  }

  // Handle numbers
  if (isNumber(cell)) {
    return <Text style={styles.cellText}>{formatNumber(cell)}</Text>;
  }

  return <Text style={styles.cellText}>{cell}</Text>;
};

export const renderHealthBenefitCell = (cell, rowIndex, colIndex, row) => {
  const { theme } = useThemeContext();
  const styles = style(theme);
  if (cell === undefined || cell === null) {
    return <Text style={[styles.cellText, styles.notApplicableText]}>-</Text>;
  }

  // If cell is ✕, show not covered
  if (cell === '✕') {
    return <Text style={[styles.cellText, styles.notCoveredIcon]}>✕</Text>;
  }

  // Handle "Covered" text
  if (cell === 'Covered') {
    return (
      <Text style={[styles.cellText, styles.applicableText]}>Covered</Text>
    );
  }

  // If cell contains HTML tags, strip them
  if (typeof cell === 'string' && (cell.includes('<') || cell.includes('>'))) {
    const cleanText = stripHtmlTags(cell);

    // Check if it's a simple covered message
    if (cleanText.toLowerCase().includes('covered') && cleanText.length < 50) {
      return (
        <Text
          style={[styles.cellText, styles.applicableText]}
        // numberOfLines={2}
        >
          {cleanText}
        </Text>
      );
    }

    // For longer descriptions
    return (
      <Text style={[styles.healthBenefitText]} /* numberOfLines={4} */>
        {cleanText}
      </Text>
    );
  }

  // Handle AED amounts
  if (typeof cell === 'string' && cell.includes('AED')) {
    return <Text style={styles.cellText}>{cell}</Text>;
  }

  // Handle percentage co-pay
  if (typeof cell === 'string' && cell.includes('%')) {
    return <Text style={styles.cellText}>{cell}</Text>;
  }

  // Handle "Not Covered"
  if (
    typeof cell === 'string' &&
    (cell.toLowerCase().includes('not covered') || cell.toLowerCase() === 'no')
  ) {
    return (
      <Text style={[styles.cellText, styles.notApplicableText]}>
        Not Covered
      </Text>
    );
  }

  // Default case - show the text
  return (
    <Text style={styles.cellText} numberOfLines={3}>
      {cell}
    </Text>
  );
};

const style = theme =>
  StyleSheet.create({
    cellText: {
      fontSize: verticalScale(14),
      fontFamily: 'Lato-Regular',
      color: theme.colors.description,
    },
    healthBenefitText: {
      fontSize: verticalScale(14),
      fontFamily: 'Lato-Regular',
      color: theme.colors.description,
    },
    applicableText: {
      color: theme.colors.lableText,
    },
    notApplicableText: {
      color: theme.colors.red,
    },
    notCoveredIcon: {
      fontSize: verticalScale(16),
      color: theme.colors.red,
      fontFamily: 'Lato-Bold',
    },
    priceText: {
      color: theme.colors.primary,
      fontFamily: 'Lato-Bold',
    },
    warningText: {
      color: theme.colors.lableThirdText,
      fontSize: verticalScale(12),
      fontFamily: 'Lato-Bold',
    },
  });

export default {
  // Motor Insurance
  renderComparisonCell,
  renderCoverageCell,
  renderBenefitCell,
  // Health Insurance
  renderHealthComparisonCell,
  renderHealthBenefitCell,
  // Utilities
  isNumber,
  stripHtmlTags,
};

import i18next from 'i18next';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { I18nManager } from 'react-native';

// helper to change language + handle RTL switching
export async function LanguageSwitcher(lng) {
  const RTL_LANGS = ['ar', 'he', 'fa', 'ur'];

  const wantRTL = RTL_LANGS.includes(lng);
  try {
    // update i18next language
    await i18next.changeLanguage(lng);
    // cache
    await AsyncStorage.setItem(LANG_KEY, lng);
  } catch (e) {
    console.warn('i18n changeLanguage error', e);
  }

  // If direction changed, force and restart to apply layout direction
  if (I18nManager.isRTL !== wantRTL) {
    try {
      // allow RTL (optional; useful if your app was disallowing)
      I18nManager.allowRTL(true);
      I18nManager.forceRTL(wantRTL);

      // RNRestart && RNRestart.Restart();
    } catch (err) {
      console.warn('Error forcing RTL:', err);
    }
  }
}

import { verticalScale } from '@constants/metrics';
import { Platform } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

const insets = useSafeAreaInsets();
export const getBottomMargin = () => {
  if (Platform.OS === 'ios') {
    return verticalScale(insets.bottom + 10);
  }
  return insets.bottom > 25
    ? verticalScale(insets.bottom + 10)
    : verticalScale(24);
};
